package ai.decisionos.aside;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import org.json.JSONObject;
/** Compatibility routes for saved shortcuts and notification targets; renders no legacy view. */
public class CompanionEntryActivity extends Activity {
 static String pageFor(String name){if(name.endsWith("CampusToolsActivity"))return "캠퍼스";if(name.endsWith("UnistCalendarActivity"))return "학사일정";if(name.endsWith("TaskActivity"))return "할 일";if(name.endsWith("ConcertTripActivity"))return "여행 비교";if(name.endsWith("LifeActivity"))return "생활 계획";if(name.endsWith("AppRegistryActivity"))return "관심 앱";if(name.endsWith("MainActivity"))return "로컬 모델";if(name.endsWith("CollectorActivity"))return "수집 설정";if(name.endsWith("PlanAssistantActivity"))return "로컬 제안";if(name.endsWith("BrowserWorkspaceActivity"))return "웹 브라우저";if(name.endsWith("CharacterWorkspaceActivity"))return "미디어";if(name.endsWith("GoalHomeActivity")||name.endsWith("UnifiedToolsActivity"))return "생활 도구";if(name.endsWith("GoalDiscoveryActivity"))return "웹 브라우저";return "";}
 public void onCreate(Bundle b){super.onCreate(b);Intent incoming=getIntent();String page=pageFor(incoming.getComponent()==null?"":incoming.getComponent().getClassName());if(incoming.hasExtra("companion_page"))page=incoming.getStringExtra("companion_page");String id=incoming.getStringExtra("goal_id");try(GoalStore store=new GoalStore(this)){try{store.goal(id);}catch(Exception e){id=null;}if(id==null){id=getSharedPreferences("nubi_navigation_v3",0).getString("lastGoal","");try{store.goal(id);}catch(Exception e){id="";}if(page==null||page.isEmpty())page=id.isEmpty()?"내 정보":"대화";}}if(page==null||page.isEmpty())page=id==null||id.isEmpty()?"내 정보":"대화";if(BuildConfig.HOME_STYLE>0&&!incoming.hasExtra("companion_page")&&incoming.getComponent()!=null&&incoming.getComponent().getClassName().endsWith("CampusActivity"))page="홈";Intent out=new Intent(this,GoalAgentActivity.class);if(incoming.getExtras()!=null)out.putExtras(incoming.getExtras());out.putExtra("goal_id",id).putExtra("companion_page",page);out.setData(incoming.getData());if(incoming.hasExtra(Intent.EXTRA_TEXT)){String shared=incoming.getStringExtra(Intent.EXTRA_TEXT);if(shared!=null)getSharedPreferences("life_plans",0).edit().putString("shared",shared.substring(0,Math.min(shared.length(),2000))).apply();}startActivity(out);finish();}
}
